    TRANSFER_TOKEN_LIFESPANS: {
        UNLIMITED: null,
        DAYS_7: 7 * DAY_IN_MS,
        DAYS_30: 30 * DAY_IN_MS,
        DAYS_90: 90 * DAY_IN_MS
    }
};

